import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageStudents() {
  const [students, setStudents] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [formData, setFormData] = useState({ 
      name: '', username: '', grade: 'Grade 10', subjects: '', phone_number: '', address: '', password: 'ST@123' 
  });

  const fetchStudents = () => {
    axios.get('http://localhost:8081/api/view-students')
      .then(res => setStudents(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => { fetchStudents(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const apiPath = isEditing ? `http://localhost:8081/api/update-student/${editId}` : 'http://localhost:8081/api/add-student';
    const method = isEditing ? axios.put : axios.post;

    method(apiPath, formData).then((res) => { 
        if(res.data.status === "Error") {
            alert("Database Error: " + res.data.error);
        } else {
            fetchStudents(); resetForm(); alert("Success!"); 
        }
    }).catch(err => alert("Error!"));
  };

  const handleEdit = (s) => {
    setIsEditing(true); setEditId(s.id);
    // 🔴 වැදගත්: මෙතනදී Database එකෙන් එන Subject (කැපිටල්) හෝ subjects (සිම්පල්) දෙකම අල්ලගන්නවා
    setFormData({ 
        name: s.name, 
        username: s.username || '', 
        grade: s.grade, 
        subjects: s.Subject || s.subjects || '', 
        phone_number: s.phone_number, 
        address: s.address || '', 
        password: 'ST@123' 
    });
    setShowForm(true);
  };

  const resetForm = () => { setShowForm(false); setIsEditing(false); setEditId(null); setFormData({ name: '', username: '', grade: 'Grade 10', subjects: '', phone_number: '', address: '', password: 'ST@123' }); };
  
  const handleSubjectChange = (sub, isChecked) => {
    let current = formData.subjects ? formData.subjects.split(', ') : [];
    if (isChecked) current.push(sub); else current = current.filter(x => x !== sub);
    setFormData({ ...formData, subjects: current.join(', ') });
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <button onClick={() => {resetForm(); setShowForm(true);}} style={{ padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>+ Register Student</button>
      
      <table style={{ width: '100%', marginTop: '20px', textAlign: 'left', borderCollapse: 'collapse' }}>
        <thead><tr style={{borderBottom: '2px solid #ddd'}}><th>Name</th><th>Grade</th><th>Subjects</th><th>Phone</th><th>Actions</th></tr></thead>
        <tbody>
          {students.map(s => (
            <tr key={s.id} style={{borderBottom: '1px solid #eee'}}>
              <td>{s.name}</td>
              <td>{s.grade}</td>
              {/* 🔴 මෙතනත් කැපිටල්/සිම්පල් දෙකටම පෙන්වනවා */}
              <td style={{fontWeight: 'bold', color: '#0369a1'}}>{s.Subject || s.subjects || '-'}</td>
              <td>{s.phone_number}</td>
              <td><button onClick={() => handleEdit(s)}>✏️ Edit</button></td>
            </tr>
          ))}
        </tbody>
      </table>

      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
          <div style={{ backgroundColor: 'white', padding: '30px', width: '400px', borderRadius: '15px' }}>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              <input type="text" placeholder="Name" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required style={{padding: '8px'}} />
              <input type="text" placeholder="Username" value={formData.username} onChange={e => setFormData({...formData, username: e.target.value})} required style={{padding: '8px'}} />
              <div style={{border: '1px solid #ccc', padding: '10px', borderRadius: '8px'}}>
                {['Mathematics', 'Science', 'English', 'ICT'].map(sub => (
                  <label key={sub} style={{display: 'block'}}><input type="checkbox" checked={(formData.subjects||'').includes(sub)} onChange={e => handleSubjectChange(sub, e.target.checked)}/> {sub}</label>
                ))}
              </div>
              <input type="text" placeholder="Phone" value={formData.phone_number} onChange={e => setFormData({...formData, phone_number: e.target.value})} required style={{padding: '8px'}} />
              <button type="submit" style={{padding: '10px', backgroundColor: '#15803d', color: 'white', border: 'none', cursor: 'pointer'}}>Save Student</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
